package com.lexorion.payroll.repository;
import com.lexorion.payroll.domain.PayRunEmployee;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface PayRunEmployeeRepository extends JpaRepository<PayRunEmployee,UUID>{List<PayRunEmployee>findByPayRunIdOrderByEmployeeCodeAsc(UUID payRunId);boolean existsByPayRunIdAndPayrollEmployeeId(UUID payRunId,UUID employeeId);long countByPayRunId(UUID payRunId);@Query("select distinct e from PayRunEmployee e join fetch e.payRun r join fetch e.calculation c left join fetch c.lines where r.workspace.id=:workspaceId and e.employeeCode=:employeeCode and r.status=com.lexorion.payroll.domain.PayRunStatus.FINALIZED order by r.periodEnd desc,r.payRunKey desc")List<PayRunEmployee>findFinalizedPayslips(@Param("workspaceId")UUID workspaceId,@Param("employeeCode")String employeeCode);@Query("select distinct e from PayRunEmployee e join fetch e.payRun r join fetch e.calculation c left join fetch c.lines where r.workspace.id=:workspaceId and e.employeeCode=:employeeCode and r.payRunKey=:payRunKey and r.status=com.lexorion.payroll.domain.PayRunStatus.FINALIZED")Optional<PayRunEmployee>findFinalizedPayslip(@Param("workspaceId")UUID workspaceId,@Param("employeeCode")String employeeCode,@Param("payRunKey")String payRunKey);}
